from collections.abc import Mapping


def merge_directory(keys, directory):
    if isinstance(keys, (str, bytes)):
        raise TypeError("keys must be a non-string iterable")
    if not isinstance(directory, Mapping):
        raise TypeError("directory must be a mapping")
    for key, value in directory.items():
        if not isinstance(key, str) or not isinstance(value, dict):
            raise TypeError("directory entries must map strings to dictionaries")

    result = []
    for key in keys:
        if not isinstance(key, str):
            raise TypeError("keys must be strings")
        if key in directory:
            result.append({"key": key, "found": True, "data": dict(directory[key])})
        else:
            result.append({"key": key, "found": False, "data": None})
    return tuple(result)

